def transform(g):
    h,w=len(g),len(g[0])
    # border flood over zeros (4-conn)
    reach=[[False]*w for _ in range(h)]; dq=deque()
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and (i in(0,h-1) or j in(0,w-1)):
                reach[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==0 and not reach[ni][nj]:
                reach[ni][nj]=True; dq.append((ni,nj))
    # label 1-components (8-conn)
    comp=[[0]*w for _ in range(h)]; nc=0
    for i in range(h):
        for j in range(w):
            if g[i][j]==1 and not comp[i][j]:
                nc+=1; dq=deque([(i,j)]); comp[i][j]=nc
                while dq:
                    a,b=dq.popleft()
                    for di in(-1,0,1):
                        for dj in(-1,0,1):
                            na,nb=a+di,b+dj
                            if 0<=na<h and 0<=nb<w and g[na][nb]==1 and not comp[na][nb]:
                                comp[na][nb]=nc; dq.append((na,nb))
    # enclosed zero regions (global flood) -> assign to adjacent components
    enclosed=[[False]*w for _ in range(h)]
    seen=[[False]*w for _ in range(h)]
    closed=set()
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and not reach[i][j] and not seen[i][j]:
                reg=[(i,j)]; seen[i][j]=True; dq=deque([(i,j)])
                while dq:
                    a,b=dq.popleft()
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+di,b+dj
                        if 0<=na<h and 0<=nb<w and g[na][nb]==0 and not reach[na][nb] and not seen[na][nb]:
                            seen[na][nb]=True; dq.append((na,nb)); reg.append((na,nb))
                adj=set()
                for a,b in reg:
                    for di in(-1,0,1):
                        for dj in(-1,0,1):
                            na,nb=a+di,b+dj
                            if 0<=na<h and 0<=nb<w and g[na][nb]==1: adj.add(comp[na][nb])
                for a,b in reg: enclosed[a][b]=True
                closed|=adj
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
