                if enclosed[i][j]:
                    out[i][j]=3
                else:
                    for di in(-1,0,1):
                        for dj in(-1,0,1):
                            na,nb=i+di,j+dj
                            if 0<=na<h and 0<=nb<w and comp[na][nb] in closed:
                                out[i][j]=2; break
    return out

